def match(pattern: str, text: str) -> bool:
    """
    Implements a backtracking algorithm for basic regex matching supporting 
    literal characters, '.', '*', and '+'. 
    """
    def is_match(p_index: int, t_index: int) -> bool:
        # If both pattern and text are fully consumed
        if p_index == len(pattern) and t_index == len(text):
            return True

        # If the pattern is fully consumed but text is not
        if p_index == len(pattern):
            return False

        # Check if the current characters match
        current_match = (t_index < len(text) and 
                         (pattern[p_index] == text[t_index] or pattern[p_index] == '.'))

        if p_index + 1 < len(pattern):
            if pattern[p_index + 1] == '*':
                # '*' can match zero occurrences of the preceding character
                if is_match(p_index + 2, t_index):
                    return True
                # '*' can match one or more occurrences if there's a match
                if current_match and is_match(p_index, t_index + 1):
                    return True
            elif pattern[p_index + 1] == '+':
                # '+' must match at least one occurrence
                if current_match and is_match(p_index, t_index + 1):
                    return True
                if current_match and is_match(p_index + 2, t_index + 1):
                    return True

        # Proceed to the next character if there's a match
        if current_match:
            return is_match(p_index + 1, t_index + 1)

        return False

    return is_match(0, 0)

