    """
    Implements a dynamic programming approach for basic regex matching supporting 
    literal characters, '.', '*', and '+'. This approach uses a 2D table to 
    store results of subproblems to avoid redundant computations.
    """
    dp = [[False] * (len(text) + 1) for _ in range(len(pattern) + 1)]
    dp[0][0] = True

    for i in range(1, len(pattern) + 1):
        if pattern[i - 1] == '*':
            dp[i][0] = dp[i - 2][0]

